css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.ls54-widget {
  --ls54-metal: #D7D8DB;
  --ls54-outline: #4E4E4E;
  --ls54-liquid: #A0CFE9;
  --ls54-fiber: #0A638F;
  --ls54-steam: #930606;
  --ls54-condensate: #4E4E4E;
  --ls54-control: #01524F;
  --ls54-valve: #0E0E55;
  --ls54-air: #756582;
  --ls54-text: #000000;

  display: grid;
  place-items: center;

  width: 100%;
  height: 100%;

  overflow: hidden;
  background: transparent;

  font-family: "Segoe UI", Arial, sans-serif;
  pointer-events: none;
}

.ls54-svg {
  display: block;

  width: 100%;
  height: 100%;

  overflow: hidden;
  background: transparent;

  shape-rendering: geometricPrecision;
}

/* Colores de los gradientes */

.ls54-metal-stop {
  stop-color: var(--ls54-metal);
}

.ls54-liquid-stop {
  stop-color: var(--ls54-liquid);
}

/* Cubas */

.ls54-tank {
  filter: url("#ls54-tank-shadow");
}

.ls54-tank-body {
  fill: url("#ls54-tank-metal");
  stroke: var(--ls54-outline);
  stroke-width: 1.8px;
  stroke-linejoin: round;
}

.ls54-tank-liquid {
  fill: url("#ls54-liquid-gradient");
  stroke: none;
}

.ls54-tank-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 0.7px;
  stroke-linecap: round;
  opacity: 0.48;
}

.ls54-tank-shade {
  fill: none;
  stroke: #555D69;
  stroke-width: 0.65px;
  stroke-linecap: round;
  opacity: 0.16;
}

/* Tuberías y conexiones */

.ls54-steam,
.ls54-condensate,
.ls54-control,
.ls54-air,
.ls54-aux-line {
  fill: none;

  stroke-width: 1.6px;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

.ls54-steam {
  stroke: var(--ls54-steam);
}

.ls54-condensate {
  stroke: var(--ls54-condensate);
}

.ls54-control {
  stroke: var(--ls54-control);
}

.ls54-air {
  stroke: var(--ls54-air);
}

.ls54-aux-line {
  stroke: var(--ls54-fiber);
}

.ls54-main {
  stroke-width: 2px;
}

.ls54-valve-connection {
  stroke-linecap: butt;
}

.ls54-control-node {
  fill: var(--ls54-control);
  stroke: none;
}

/* Válvulas */

.ls54-valve-body {
  fill: none;
  stroke: var(--ls54-valve);
  stroke-width: 1.4px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ls54-valve-stem {
  fill: none;
  stroke: var(--ls54-valve);
  stroke-width: 0.7px;
  stroke-linecap: butt;
}

.ls54-valve-actuator {
  fill: var(--ls54-valve);
  stroke: var(--ls54-valve);
  stroke-width: 1px;
}

/* Cuerda */

.ls54-fiber {
  fill: none;
  stroke: var(--ls54-fiber);
  stroke-width: 1.8px;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

/* Poleas */

.ls54-roller-body {
  fill: url("#ls54-roller-metal");
  stroke: var(--ls54-outline);
  stroke-width: 2.2px;

  filter: url("#ls54-roller-shadow");
}

.ls54-roller-number {
  fill: var(--ls54-text);
  stroke: none;

  font-family: "IBM Plex Mono", Consolas, monospace;
  font-size: 13px;
  font-weight: 700;

  text-anchor: middle;
  dominant-baseline: middle;
}

/* Aire comprimido */

.ls54-air-box {
  fill: url("#ls54-tank-metal");
  stroke: var(--ls54-air);
  stroke-width: 1.6px;
  stroke-linejoin: round;
}

.ls54-arrow {
  fill: var(--ls54-fiber);
  stroke: none;
}

.ls54-air-arrow {
  fill: var(--ls54-air);
}

.ls54-air-label {
  fill: var(--ls54-air);

  font-size: 10px;
  font-weight: 400;
  text-anchor: middle;
}

/* Accesorios metálicos */

.ls54-hardware {
  fill: url("#ls54-hardware-metal");
  stroke: var(--ls54-outline);
  stroke-width: 1px;
  stroke-linejoin: round;
}

.ls54-hardware-detail {
  fill: none;
  stroke: var(--ls54-outline);
  stroke-width: 1px;
  stroke-linecap: round;
}

/* Textos */

.ls54-label {
  fill: var(--ls54-text);
  font-size: 13px;
  font-weight: 700;
}

.ls54-steam-label {
  fill: var(--ls54-steam);
  font-size: 12px;
  font-weight: 600;
}

.ls54-condensate-label {
  fill: var(--ls54-condensate);
  font-size: 12px;
  font-weight: 600;
}

.ls54-footer {
  fill: var(--ls54-text);
  font-size: 16px;
  font-style: italic;
  font-weight: 500;
  text-anchor: end;
}

